export class CTimer {

	t0 = Date.now()

	timeTaken(
			reset: boolean = true,
			decPlaces: number = 2
			): string {

		const now = Date.now()
		const secs = (now - this.t0) / 1000
		if (reset) {
			this.t0 = now
		}
		return sprintf(`%.${decPlaces}d`, secs)
	}
}

const timer = new CTimer()

// ---------------------------------------------------------------------------

export abstract class CFileHandler {

	abstract get op(): string

	// ..........................................................
	// ASYNC

	abstract handle(
			path: string,
			hOptions: hash
			): Promise<TExecResult>

	// ..........................................................
	// SYNC

	getOutput(hResult: TExecResult): string {

		return (hResult?.stdout || '') + (hResult?.stderr || '')
	}
}

// ---------------------------------------------------------------------------

export const prelog = (
		op: string,
		path: string,
		capture: boolean
		): void => {

	if (capture) {
		writeln(`${op} ${relpath(path)}`)
	}     // was just write
	else {
		writeln(`${op} ${relpath(path)} (no capture)`)
	}
	return
}

// ---------------------------------------------------------------------------
// --- only call if capture was true

export const postlog = (
		success: boolean,
		notNeeded: (boolean | undefined)
		): void => {

	if (success) {
		if (notNeeded) {
			writeln(f`${' - not needed'}:{yellow}`)
		}
		else {
			writeln(f`${' - OK'}:{green}`)
		}
	}
	else {
		writeln(` ${colorize('FAILED', 'red')}`)
	}
	return
}

